code='''def transform(grid):
    out = [row[:] for row in grid]
    h, w = len(grid), len(grid[0])
    # Find the non-background color and the dominant background color.
    from collections import Counter
    counts = Counter(v for row in grid for v in row)
    bg = counts.most_common(1)[0][0]
    fg = next((v for v, n in counts.most_common() if v != bg), None)
    if fg is None:
        return out

    # A long horizontal bar with only background after it is extended in marker color.
    # Restrict to long runs to avoid changing the short strokes that make up motifs.
    for r, row in enumerate(grid):
        best = (0, -1, -1)
        c = 0
        while c < w:
            if row[c] != fg:
                c += 1
                continue
            a = c
            while c < w and row[c] == fg:
                c += 1
            if c-a > best[0]:
                best = (c-a, a, c)
        length, a, end = best
        if length >= max(3, w//4) and end < w and all(x == bg for x in row[end:]):
            # Require this to be a dominant stripe within its locally connected band.
            nearby = [max_run(grid[rr], fg) for rr in range(max(0,r-1), min(h,r+2)) if rr != r]
            if not nearby or length >= max(nearby):
                for cc in range(end, w):
                    out[r][cc] = 1

    # Repeated horizontal blocks: retain the first block as the pattern and mark
    # foreground pixels in later exact copies. This handles the repeated 3-cell
    # tail motifs used as continuation patterns in the task.
    for r, row in enumerate(grid):
        for p in range(1, min(8, w//2)+1):
            # Find a suffix containing at least three copies of a period-p block.
            for start in range(w-3*p, -1, -1):
                if start + 3*p > w:
                    continue
                if all(row[start+i] == row[start+i % p] for i in range(w-start)):
                    # Require two or more full repeated blocks and a nontrivial pattern.
                    if w-start >= 3*p and len(set(row[start:start+p])) > 1:
                        # Locate the first two equal blocks and mark later copies.
                        for cc in range(start+p, w):
                            if row[cc] == fg:
                                out[r][cc] = 1
                        break
            else:
                continue
            break
    return out

def max_run(row, color):
    best = run = 0
    for x in row:
        if x == color:
            run += 1
            best = max(best, run)
        else:
            run = 0
    return best
'''
